package com.codelens.service;
import com.codelens.domain.ReviewTask; import com.codelens.repo.ReviewTaskRepository; import com.fasterxml.jackson.databind.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.Instant; import java.util.Set;
@Service public class ReviewTaskService { private final ReviewTaskRepository tasks; private final StringRedisTemplate redis; private final ObjectMapper json=new ObjectMapper(); @Value("${codelens.webhook-secret}") String secret; @Value("${codelens.queue-key}") String queue;
 public ReviewTaskService(ReviewTaskRepository t,StringRedisTemplate r){tasks=t;redis=r;}
 @Transactional public void accept(String token,String event,String body){if(!secret.equals(token)) throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.UNAUTHORIZED,"invalid webhook secret"); try{JsonNode root=json.readTree(body), attrs=root.path("object_attributes"), project=root.path("project"); if(!"merge_request".equalsIgnoreCase(root.path("object_kind").asText()) && !event.toLowerCase().contains("merge")) return; String action=attrs.path("action").asText(); String sha=attrs.path("last_commit").path("id").asText(); if(sha.isBlank()) sha=attrs.path("last_commit_id").asText(); long pid=project.path("id").asLong(root.path("project").path("id").asLong()); long iid=attrs.path("iid").asLong(); if(Set.of("merge","close").contains(action)) return; String key=pid+":"+iid+":"+sha; if(tasks.findByIdempotencyKey(key).isPresent()) return; ReviewTask t=new ReviewTask(); t.idempotencyKey=key;t.projectId=pid;t.mrIid=iid;t.headSha=sha;t.status=ReviewTask.Status.QUEUED;t.queuedAt=Instant.now(); t.complexity="MEDIUM"; tasks.save(t); redis.opsForList().rightPush(queue,t.id.toString()); }catch(Exception e){throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"invalid webhook payload");}}
}
